create extension if not exists pgcrypto;
create type public.user_role as enum ('coach','student');
create type public.proof_status as enum ('pending','approved','rejected');
create type public.vod_status as enum ('pending','reviewed');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,full_name text not null,role public.user_role not null default 'student',current_rank text,target_rank text,coach_id uuid references public.profiles(id),is_active boolean not null default false,subscription_expires_at timestamptz,created_at timestamptz not null default now());
create table public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,stripe_customer_id text,stripe_subscription_id text unique,status text not null default 'inactive',plan_type text,expires_at timestamptz,created_at timestamptz not null default now());
create table public.payment_proofs(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,pix_key text not null,receipt_url text,status public.proof_status not null default 'pending',created_at timestamptz not null default now(),reviewed_at timestamptz);
create table public.training_routines(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,coach_id uuid not null references public.profiles(id),title text not null,category text not null,is_completed boolean not null default false,description text,scheduled_for date not null default current_date,completed_at timestamptz,created_at timestamptz not null default now());
create table public.vod_reviews(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,coach_id uuid references public.profiles(id),student_youtube_url text not null,coach_review_youtube_url text,map text not null,agent text not null,coach_notes text,recurring_errors text,status public.vod_status not null default 'pending',created_at timestamptz not null default now());
create table public.live_sessions(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,coach_id uuid not null references public.profiles(id),title text not null default 'Sessão ao vivo',stream_url text not null,notes text not null default '',scheduled_at timestamptz not null,status text not null default 'scheduled',updated_at timestamptz not null default now());
create table public.rank_history(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,rank text not null,recorded_at timestamptz not null default now());
create table public.coupons(id uuid primary key default gen_random_uuid(),code text unique not null,percent_off int not null check(percent_off between 1 and 100),active boolean not null default true,expires_at timestamptz);
create table public.coupon_redemptions(id uuid primary key default gen_random_uuid(),coupon_id uuid not null references public.coupons(id),user_id uuid not null references public.profiles(id),redeemed_at timestamptz not null default now(),unique(coupon_id,user_id));
create or replace function public.is_coach() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='coach') $$;
alter table public.profiles enable row level security; alter table public.subscriptions enable row level security; alter table public.payment_proofs enable row level security; alter table public.training_routines enable row level security; alter table public.vod_reviews enable row level security; alter table public.live_sessions enable row level security; alter table public.rank_history enable row level security; alter table public.coupons enable row level security; alter table public.coupon_redemptions enable row level security;
create policy profiles_read on public.profiles for select using(id=auth.uid() or public.is_coach() or coach_id=auth.uid()); create policy profiles_update on public.profiles for update using(id=auth.uid() or public.is_coach());
create policy subscriptions_read on public.subscriptions for select using(user_id=auth.uid() or public.is_coach()); create policy proofs_access on public.payment_proofs for all using(user_id=auth.uid() or public.is_coach()) with check(user_id=auth.uid() or public.is_coach());
create policy routines_access on public.training_routines for all using(student_id=auth.uid() or coach_id=auth.uid() or public.is_coach()) with check(student_id=auth.uid() or coach_id=auth.uid() or public.is_coach()); create policy vods_access on public.vod_reviews for all using(student_id=auth.uid() or coach_id=auth.uid() or public.is_coach()) with check(student_id=auth.uid() or coach_id=auth.uid() or public.is_coach()); create policy live_access on public.live_sessions for all using(student_id=auth.uid() or coach_id=auth.uid() or public.is_coach()) with check(student_id=auth.uid() or coach_id=auth.uid() or public.is_coach()); create policy rank_access on public.rank_history for all using(student_id=auth.uid() or public.is_coach()) with check(student_id=auth.uid() or public.is_coach()); create policy coupons_read on public.coupons for select using(active); create policy redemption_access on public.coupon_redemptions for all using(user_id=auth.uid() or public.is_coach()) with check(user_id=auth.uid() or public.is_coach());
